import assert from "node:assert/strict";
import test from "node:test";
import { nativeSource } from "./helpers/native-source.mjs";
const policy = await nativeSource("lib/storage-policy.ts");
const api = await nativeSource("lib/storage-cleanup.ts", { ...policy, activeStorageProvider: () => "s3" });

test("cleanup records snapshot a provider and reject broad prefixes and malformed operation context", () => {
  assert.equal(api.cleanupTarget({ key: "private/file.txt", source: "qa" }).provider, "s3");
  const key = "private/video-derived/42/a55b3b39-2045-46e5-b52b-0f69187f9d32";
  assert.equal(api.cleanupTarget({ key, source: "qa", recursive: true }).kind, "prefix");
  for (const invalid of ["private", "private/video-derived", "private/video-derived/42", key + "/child", "../outside", "a//b"]) {
    assert.throws(() => api.cleanupTarget({ key: invalid, source: "qa", recursive: true }));
  }
  assert.throws(() => api.cleanupTarget({ key, source: "qa", provider: "unknown" }));
  assert.throws(() => api.cleanupTarget({ key, source: "qa", provider: "local", uploadId: "fake" }));
  assert.throws(() => api.cleanupTarget({ key: "private/video-source/a.mp4", source: "qa", uploadId: "bad\nvalue" }));
});

test("cleanup retry backoff is finite, bounded and never implies discarding failed work", () => {
  assert.equal(api.cleanupRetrySeconds(1), 5);
  assert.equal(api.cleanupRetrySeconds(2), 10);
  assert.equal(api.cleanupRetrySeconds(1000), 21600);
  for (const value of [0, -1, NaN, Infinity, 1.5]) assert.throws(() => api.cleanupRetrySeconds(value));
});

test("legacy source cleanup waits beyond signature expiry instead of reopening a valid PUT URL", () => {
  assert.equal(api.cleanupInitialDelayMs(api.cleanupTarget({key:"private/video-source/lesson/old.mp4",source:"video",provider:"s3"})),16*60_000);
  assert.equal(api.cleanupInitialDelayMs(api.cleanupTarget({key:"private/video-source/lesson/mp-a55b3b39-2045-46e5-b52b-0f69187f9d32.mp4",source:"video",provider:"s3"})),0);
  assert.equal(api.cleanupInitialDelayMs(api.cleanupTarget({key:"private/video-source/lesson/old.mp4",source:"video",provider:"local"})),0);
});
